package io.atlas.modules.market.menu;
import io.atlas.modules.market.MarketModule;import io.atlas.modules.market.model.*;import io.atlas.modules.market.repository.MarketRepository.*;import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.ItemLore;import net.minecraft.world.SimpleContainer;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import java.util.*;
public final class MarketMenu extends ChestMenu {
 private final MarketBrowse browse;private final List<Listing> listings;private final Draft draft;private final Listing detail;private boolean used;
 public MarketMenu(int id,Inventory inventory,String kind,boolean own,int page,String search,List<Listing> listings,Draft draft,Listing detail){this(id,inventory,MarketBrowse.defaults(kind,own,page,search),listings,draft,detail);}
 public MarketMenu(int id,Inventory inventory,MarketBrowse browse,List<Listing> listings,Draft draft,Listing detail){super(MenuType.GENERIC_9x4,id,inventory,contents((ServerPlayer)inventory.player,browse,listings,draft,detail),4);this.browse=browse;this.listings=List.copyOf(listings);this.draft=draft;this.detail=detail;}
 static ItemStack preview(ServerPlayer p,String kind,String payload,String name,long price,String owner){return MarketVisual.preview(p,kind,payload,name,price,owner,io.atlas.modules.lobby.service.DevEnvironment.DEVELOPMENT?"Testes":"Emerald",null);}
 private static ItemStack preview(ServerPlayer p,Listing l){return MarketVisual.preview(p,l.kind(),l.payload(),l.name(),l.price(),l.sellerName(),l.serverName(),l.expiresAt());}
 private static SimpleContainer contents(ServerPlayer p,MarketBrowse b,List<Listing> listings,Draft draft,Listing detail){var c=new SimpleContainer(36);
  if(draft!=null){c.setItem(13,MarketVisual.preview(p,draft.kind(),draft.payload(),draft.name(),draft.price(),draft.sellerName(),draft.serverName(),null));c.setItem(21,MarketVisual.icon(Items.EMERALD,"§aConfirmar anúncio","§7Preço total: "+MarketPolicy.formatPrice(draft.price())+" CobbleDollars","§7Duração: "+MarketPolicy.duration(draft.durationSeconds()),"§7O bem será retirado após publicar."));c.setItem(23,MarketVisual.icon(Items.BARRIER,"§cCancelar"));return c;}
  if(detail!=null){c.setItem(13,preview(p,detail));if(detail.state().equals("ACTIVE")&&detail.expiresAt()!=null&&detail.expiresAt().isAfter(java.time.Instant.now())){boolean seller=detail.seller().equals(p.getUUID());c.setItem(21,MarketVisual.icon(seller?Items.BARRIER:Items.EMERALD,seller?"§cCancelar e devolver":"§aConfirmar compra","§7Preço total: "+MarketPolicy.formatPrice(detail.price())+" CobbleDollars",seller?"§7O bem voltará ao inventário/equipe/PC.":"§7O valor será descontado do saldo."));}else c.setItem(21,MarketVisual.icon(Items.PAPER,"§7"+status(detail)));c.setItem(31,MarketVisual.icon(Items.ARROW,"§eVoltar"));return c;}
  for(int i=0;i<Math.min(27,listings.size());i++){var l=listings.get(i);var stack=preview(p,l);var lore=new ArrayList<Component>(stack.getOrDefault(DataComponents.LORE,new ItemLore(List.of())).lines());lore.add(Component.literal(b.own()?"§e"+status(l):"§eClique para ver e confirmar a compra."));stack.set(DataComponents.LORE,new ItemLore(lore));c.setItem(i,stack);}
  if(listings.isEmpty())c.setItem(13,MarketVisual.icon(Items.PAPER,"§7Nenhum anúncio encontrado"));if(b.page()>0)c.setItem(27,MarketVisual.icon(Items.ARROW,"§ePágina anterior"));c.setItem(28,MarketVisual.icon(Items.CHEST,b.own()?"§bVer GTS":"§bMeus anúncios","§bEsquerdo: alternar anúncios","§6Direito: receber ganhos"));c.setItem(29,MarketVisual.icon(Items.BOOK,"§aAnunciar","§7Escolha Pokémon ou item, preço e duração."));c.setItem(30,MarketVisual.icon(Items.HOPPER,"§bMostrar: "+(b.kind().equals("ALL")?"Todos":b.kind().equals("ITEM")?"Itens":"Pokémon"),"§7Esquerdo: próximo • direito: anterior"));c.setItem(31,MarketVisual.icon(Items.CLOCK,"§eAtualizar","§7Página "+(b.page()+1)));var sorts=new ArrayList<String>();for(var s:MarketBrowse.Sort.values())sorts.add((s==b.sort()?"§a▶ ":"§8• ")+s.label);sorts.add("§bEsquerdo: próximo • §eDireito: anterior");c.setItem(32,MarketVisual.icon(new ItemStack(Items.COMPASS),"§eOrdenar anúncios",sorts));if(listings.size()>27)c.setItem(35,MarketVisual.icon(Items.ARROW,"§ePróxima página"));var items=new ArrayList<String>();for(var f:MarketBrowse.ItemFilter.values())items.add((b.kind().equals("ITEM")&&f==b.itemFilter()?"§a▶ ":"§8• ")+f.label);items.add("§bEsquerdo: próximo • §eDireito: anterior");c.setItem(33,MarketVisual.icon(new ItemStack(Items.DIAMOND),"§aFiltro de itens",items));var pokemon=new ArrayList<String>();for(var f:MarketBrowse.PokemonFilter.values())pokemon.add((f==b.pokemonFilter()?"§a▶ ":"§8• ")+f.label);pokemon.add("§bEsquerdo: próximo • §eDireito: anterior");c.setItem(34,MarketVisual.icon(new ItemStack(Items.NETHER_STAR),"§aFiltro de Pokémon",pokemon));return c;
 }
 private static String status(Listing l){if(l.state().equals("SOLD"))return switch(l.credit()){case "AVAILABLE"->"Vendido • ganhos disponíveis";case "PAID"->"Vendido • ganhos recebidos";case "REVIEW"->"Vendido • pagamento em conferência";default->"Vendido • pagamento em andamento";};if("EXPIRED".equals(l.endReason()))return l.state().equals("CANCELLED")?"Expirado • bem devolvido":"Expirado • devolução pendente";return switch(l.state()){case "ACTIVE"->"Disponível";case "CANCELLED"->"Cancelado • bem devolvido";case "REVIEW"->"Aguardando conferência da staff";default->"Em processamento";};}
 @Override public void clicked(int slot,int button,ClickType type,Player player){if(!(player instanceof ServerPlayer p)||type!=ClickType.PICKUP||used||(button!=0&&button!=1))return;var service=MarketModule.service();if(draft!=null){if(slot==21){used=true;service.publish(p,draft);}else if(slot==23){used=true;service.open(p,"ALL",false,0,"");}return;}if(detail!=null){if(slot==21&&detail.state().equals("ACTIVE")){used=true;if(detail.seller().equals(p.getUUID()))service.cancel(p,detail.id());else service.buy(p,detail.id());}else if(slot==31){used=true;service.open(p,browse);}return;}if(slot>=0&&slot<Math.min(27,listings.size())){used=true;service.inspect(p,listings.get(slot).id(),browse);}else if(slot==30){used=true;String[] kinds={"ALL","POKEMON","ITEM"};int index=Arrays.asList(kinds).indexOf(browse.kind());service.open(p,browse.kind(kinds[Math.floorMod(index+(button==0?1:-1),3)]));}else if(slot==32||slot==33||slot==34){used=true;service.open(p,slot==32?browse.sort(button==0):slot==33?browse.items(button==0):browse.pokemon(button==0));}else if(slot==28&&button==1){used=true;p.closeContainer();service.withdraw(p,"ALL");}else if(slot==28||slot==31||slot==27&&browse.page()>0||slot==35&&listings.size()>27){used=true;service.open(p,slot==28?browse.own(!browse.own()):browse.page(slot==27?browse.page()-1:slot==35?browse.page()+1:browse.page()));}else if(slot==29){used=true;service.announce(p);}}
 @Override public ItemStack quickMoveStack(Player player,int slot){return ItemStack.EMPTY;}
}
